import { Jimp } from "jimp";
import fs from "fs";

// Native Android mipmap launcher icons are NOT regenerated by gen-assets.mjs
// (that script only writes assets/icon.png etc.) — they're normally synced by
// `expo prebuild`, but that wipes the release signing config in this project,
// so it isn't re-run casually. This script re-syncs just the mipmap PNGs from
// the current assets/icon.png + assets/adaptive-icon.png without touching
// anything else in android/.

const RES = "E:/obscura/mobile/android/app/src/main/res";
const ASSETS = "E:/obscura/mobile/assets";

const DENSITIES = {
  mdpi: 108, hdpi: 162, xhdpi: 216, xxhdpi: 324, xxxhdpi: 432,
};

function applyCircleMask(img) {
  const { data, width, height } = img.bitmap;
  const cx = width / 2, cy = height / 2, r = width / 2;
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const dx = x - cx + 0.5, dy = y - cy + 0.5;
      if (dx * dx + dy * dy > r * r) {
        const i = (y * width + x) * 4;
        data[i + 3] = 0;
      }
    }
  }
  return img;
}

const legacySrc = await Jimp.read(`${ASSETS}/icon.png`);
const foregroundSrc = await Jimp.read(`${ASSETS}/adaptive-icon.png`);

for (const [density, size] of Object.entries(DENSITIES)) {
  const dir = `${RES}/mipmap-${density}`;

  const legacy = legacySrc.clone().resize({ w: size, h: size });
  await legacy.write(`${dir}/ic_launcher.png`);

  const round = legacySrc.clone().resize({ w: size, h: size });
  applyCircleMask(round);
  await round.write(`${dir}/ic_launcher_round.png`);

  const foreground = foregroundSrc.clone().resize({ w: size, h: size });
  await foreground.write(`${dir}/ic_launcher_foreground.png`);

  console.log(`mipmap-${density} (${size}x${size}) ✓`);
}
